{"code": "import copy
import pytest

import impl


def test_empty_input_returns_empty_list():
    assert impl.merge_bookings([]) == []


def test_single_booking_returned_unchanged():
    assert impl.merge_bookings([(60, 120)]) == [(60, 120)]


def test_touching_bookings_merge_into_one_block():
    assert impl.merge_bookings([(60, 120), (120, 180)]) == [(60, 180)]


def test_gap_of_one_minute_keeps_blocks_separate():
    result = impl.merge_bookings([(60, 120), (121, 180)])
    assert result == [(60, 120), (121, 180)]


def test_zero_length_entry_is_dropped_and_does_not_bridge():
    result = impl.merge_bookings([(0, 60), (90, 90), (120, 180)])
    assert result == [(0, 60), (120, 180)]


def test_all_zero_length_entries_yield_empty_list():
    assert impl.merge_bookings([(5, 5), (10, 10), (-3, -3)]) == []


def test_exact_duplicates_collapse_to_one_block():
    assert impl.merge_bookings([(60, 120), (60, 120)]) == [(60, 120)]


def test_nested_interval_is_absorbed_by_outer():
    assert impl.merge_bookings([(60, 300), (120, 180)]) == [(60, 300)]


def test_negative_minutes_merge_across_midnight():
    assert impl.merge_bookings([(-60, 0), (0, 60)]) == [(-60, 60)]


def test_unsorted_input_is_sorted_in_output():
    result = impl.merge_bookings([(700, 720), (480, 540), (600, 630)])
    assert result == [(480, 540), (600, 630), (700, 720)]


def test_list_entries_accepted_output_is_tuples():
    result = impl.merge_bookings([[60, 120], [120, 180]])
    assert result == [(60, 180)]
    for block in result:
        assert type(block) is tuple


def test_worked_example_from_ticket():
    result = impl.merge_bookings(
        [(540, 600), (600, 630), (630, 630), (700, 720), (690, 700), (480, 540)]
    )
    assert result == [(480, 630), (690, 720)]


def test_start_greater_than_end_raises_with_pair_in_message():
    with pytest.raises(ValueError) as excinfo:
        impl.merge_bookings([(120, 60)])
    assert "(120, 60)" in str(excinfo.value)


def test_start_equals_end_is_not_an_error():
    # Should not raise; it's silently dropped.
    assert impl.merge_bookings([(615, 615)]) == []


def test_entry_with_wrong_length_raises_value_error():
    with pytest.raises(ValueError):
        impl.merge_bookings([(60, 120, 180)])


def test_entry_not_tuple_or_list_raises_value_error():
    with pytest.raises(ValueError):
        impl.merge_bookings(["60,120"])


def test_non_int_bounds_raise_value_error():
    with pytest.raises(ValueError):
        impl.merge_bookings([(60.0, 120)])


def test_bool_bounds_raise_value_error():
    # bool is a subclass of int but must be rejected explicitly.
    with pytest.raises(ValueError):
        impl.merge_bookings([(True, 120)])


def test_input_list_and_entries_are_not_mutated():
    original = [(120, 180), (60, 120)]
    snapshot = copy.deepcopy(original)
    impl.merge_bookings(original)
    assert original == snapshot


def test_disjoint_non_touching_blocks_all_present_and_ordered():
    result = impl.merge_bookings([(200, 210), (0, 10), (100, 110)])
    assert result == [(0, 10), (100, 110), (200, 210)]
